5	 * You may obtain a copy of Mulan PSL v2 at:
6	 *          http://license.coscl.org.cn/MulanPSL2
7	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND,
8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Gu, Zihan
12	// Description:vector alu(soft_thread==hard_thread)
13	`timescale 1ns/1ns
14	`include "define.v"
15	//`include "IDecode_define.v"
16	
17	module  valu #(
18	  parameter SOFT_THREAD = `NUM_THREAD,
19	  parameter HARD_THREAD = `NUM_THREAD
20	  )(
21	  input                                     clk              ,
22	  input                                     rst_n            ,
23	
24	  input                                     in_valid_i       ,
25	  input                                     out_ready_i      ,
26	  input                                     out2simt_ready_i ,
27	
28	  input   [SOFT_THREAD*`XLEN-1:0]           in1_i            ,
29	  input   [SOFT_THREAD*`XLEN-1:0]           in2_i            ,
30	  //input   [SOFT_THREAD*`XLEN-1:0]           in3_i            ,
31	  input   [SOFT_THREAD-1:0]                 mask_i           ,
32	  input   [5:0]                             ctrl_alu_fn_i    ,
33	  input                                     ctrl_reverse_i   ,
34	  //input                                     ctrl_writemask_i ,
35	  //input                                     ctrl_readmask_i  ,
36	  input                                     ctrl_simt_stack_i,
37	  input   [`DEPTH_WARP-1:0]                 ctrl_wid_i       ,
38	  input   [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] ctrl_reg_idxw_i  ,
39	  input                                     ctrl_wvd_i       ,
40	
41	  output                                    in_ready_o       ,
42	  output                                    out_valid_o      ,
43	  output                                    out2simt_valid_o ,
44	
45	  output  [SOFT_THREAD*`XLEN-1:0]           wb_wvd_rd_o      ,
46	  output  [SOFT_THREAD-1:0]                 wvd_mask_o       ,
47	  output                                    wvd_o            ,
48	  output  [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] reg_idxw_o       ,
49	  output  [`DEPTH_WARP-1:0]                 warp_id_o        ,
50	
51	  output  [SOFT_THREAD-1:0]                 if_mask_o        ,
52	  output  [`DEPTH_WARP-1:0]                 wid_o             
53	);                                                       
54	
55	  //result输入数据
56	  wire   [SOFT_THREAD*`XLEN+SOFT_THREAD+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-1:0] result_data_in     ;
57	  wire   [SOFT_THREAD*`XLEN+SOFT_THREAD+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-1:0] result_data_out    ;
58	  wire                                                                                 result_in_valid    ;
59	  wire                                                                                 result_in_ready    ;
60	  wire                                                                                 result_out_valid   ;
61	  wire                                                                                 result_out_ready   ;
62	
63	  //result_simt输入数据
64	  wire   [`DEPTH_WARP+SOFT_THREAD-1:0]  result_simt_data_in  ;
65	  wire   [`DEPTH_WARP+SOFT_THREAD-1:0]  result_simt_data_out ;
66	  wire                                  result_simt_in_valid ;
67	  wire                                  result_simt_in_ready ;
68	  wire                                  result_simt_out_valid;
69	  wire                                  result_simt_out_ready;
70	
71	  //alu
72	  reg    [`XLEN*HARD_THREAD-1:0]        alu_in1                  ;
73	  reg    [`XLEN*HARD_THREAD-1:0]        alu_in2                  ;
74	  //reg    [`XLEN*HARD_THREAD-1:0]        alu_in3                  ;
75	  reg    [5*HARD_THREAD-1:0]            alu_op                   ;
76	  wire   [`XLEN-1:0]                    alu_out [0:HARD_THREAD-1];
77	  wire                                  alu_cmp [0:HARD_THREAD-1];
78	  
79	  wire   [HARD_THREAD-1:0]              if_mask                  ;
80	  wire   [SOFT_THREAD*`XLEN-1:0]        wb_wvd_rd_comb           ;
81	  //reg    [`XLEN-1:0]                    wb_wvd_rd [0:HARD_THREAD-1];
82	  reg    [`XLEN*HARD_THREAD-1:0]        wb_wvd_rd                ;
83	  reg    [HARD_THREAD-1:0]              wvd_mask                 ;
84	  reg    [`XLEN-1:0]                    temp;
85	
86	  genvar i;
87	  generate
88	    for(i=0;i<HARD_THREAD;i=i+1) begin:alu
89	      alu #(.OPCODE_WIDTH(5)) U_alu_i(
90	        //.clk  (clk                          ),
91	        //.rst_n(rst_n                        ),
92	        .op_i (alu_op[(i+1)*5-1-:5]        ),
93	        .in1_i(alu_in1[(i+1)*`XLEN-1-:`XLEN]),
94	        .in2_i(alu_in2[(i+1)*`XLEN-1-:`XLEN]),
95	        //.in3_i(alu_in3[(i+1)*`XLEN-1-:`XLEN]),
96	        .out_o(alu_out[i]                   ),
97	        .cmp_o(alu_cmp[i]                   )
98	      );
99	
100	      assign wb_wvd_rd_comb[(i+1)*`XLEN-1-:`XLEN] = wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN];
101	      assign if_mask[i] = ~alu_cmp[i];
102	
103	      always@(*) begin
104	        if(ctrl_reverse_i == 1'b1) begin
105	          alu_op[(i+1)*5-1-:5]            = ctrl_alu_fn_i[4:0];
106	          alu_in1[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
107	          alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in1_i[(i+1)*`XLEN-1-:`XLEN];
108	          //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
109	          wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = alu_out[i];
110	          wvd_mask[i]                     = mask_i[i];
111	        end
112	
113	        else if((ctrl_alu_fn_i == `FN_VMANDNOT) | (ctrl_alu_fn_i == `FN_VMORNOT) | (ctrl_alu_fn_i == `FN_VMNAND) |
114	                (ctrl_alu_fn_i == `FN_VMNOR) | (ctrl_alu_fn_i == `FN_VMXNOR)) begin
115	          if((ctrl_alu_fn_i == `FN_VMANDNOT) | (ctrl_alu_fn_i == `FN_VMORNOT)) begin
116	            alu_op[(i+1)*5-1-:5]            = {4'd3,ctrl_alu_fn_i[0]};
117	            alu_in1[(i+1)*`XLEN-1-:`XLEN]   = ~in1_i[(i+1)*`XLEN-1-:`XLEN];
118	            alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
119	            //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
120	            wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = alu_out[i];
121	            wvd_mask[i]                     = mask_i[i];
122	          end
123	          else begin
124	            if(ctrl_alu_fn_i == `FN_VMXNOR) begin
125	              alu_op[(i+1)*5-1-:5]            = `FN_XOR;
126	              alu_in1[(i+1)*`XLEN-1-:`XLEN]   = in1_i[(i+1)*`XLEN-1-:`XLEN];
127	              alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
128	              //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
129	              wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = ~alu_out[i];
130	              wvd_mask[i]                     = mask_i[i];
131	            end
132	            else begin
133	              alu_op[(i+1)*5-1-:5]            = {4'd3,ctrl_alu_fn_i[0]};
134	              alu_in1[(i+1)*`XLEN-1-:`XLEN]   = in1_i[(i+1)*`XLEN-1-:`XLEN];
135	              alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
136	              //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
137	              wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = ~alu_out[i];
138	              wvd_mask[i]                     = mask_i[i];
139	            end
140	          end
141	        end
142	        
143	        else if(ctrl_alu_fn_i == `FN_VID) begin
144	          alu_op[(i+1)*5-1-:5]            = ctrl_alu_fn_i[4:0];
145	          alu_in1[(i+1)*`XLEN-1-:`XLEN]   = in1_i[(i+1)*`XLEN-1-:`XLEN];
146	          alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
147	          //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
148	          wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = i;
149	          wvd_mask[i]                     = mask_i[i];
150	        end
151	
152	        else if(ctrl_alu_fn_i == `FN_VMERGE) begin
153	          alu_op[(i+1)*5-1-:5]            = ctrl_alu_fn_i[4:0];
154	          alu_in1[(i+1)*`XLEN-1-:`XLEN]   = in1_i[(i+1)*`XLEN-1-:`XLEN];
155	          alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
156	          //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
157	          wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = mask_i[i] ? in1_i[(i+1)*`XLEN-1-:`XLEN] : in2_i[(i+1)*`XLEN-1-:`XLEN];
158	          wvd_mask[i]                     = 1'b1;
159	        end
160	
161	        else begin
162	          alu_op[(i+1)*5-1-:5]            = ctrl_alu_fn_i[4:0];
163	          alu_in1[(i+1)*`XLEN-1-:`XLEN]   = in1_i[(i+1)*`XLEN-1-:`XLEN];
164	          alu_in2[(i+1)*`XLEN-1-:`XLEN]   = in2_i[(i+1)*`XLEN-1-:`XLEN];
165	          //alu_in3[(i+1)*`XLEN-1-:`XLEN]   = in3_i[(i+1)*`XLEN-1-:`XLEN];
166	          wb_wvd_rd[(i+1)*`XLEN-1-:`XLEN] = alu_out[i];
167	          wvd_mask[i]                     = mask_i[i];
168	        end
169	      end
170	    end
171	  endgenerate
172	
173	  //writemask恒为0，不需要考虑
174	  /*genvar j;
175	  generate
176	    for(j=0;j<HARD_THREAD;j=j+1) begin
177	      always@(*) begin
178	        if(ctrl_writemask_i) begin
179	          wb_wvd_rd[0] = ctrl_readmask_i ? alu_out[0] : temp;
180	          temp[j]      = mask_i[j] ? alu_out[j][0] : 1'b0;
181	          wvd_mask[0]  = 1'b1;
182	          if(ctrl_alu_fn_i == `FN_VMNAND | ctrl_alu_fn_i == `FN_VMXNOR | ctrl_alu_fn_i == `FN_VMXNOR) begin
183	            wb_wvd_rd[0][j] = mask_i[j] ? !alu_out[j][0] : 1'b0;
184	            wvd_mask[j] = mask_i[j];
185	          end
186	          else begin
187	            wb_wvd_rd[j] = alu_out[j];
188	            wvd_mask[j] = mask_i[j];
189	          end
190	        end
191	        else begin
192	          wb_wvd_rd[j] = alu_out[j];
193	          wvd_mask[j] = mask_i[j];
194	        end
195	      end
196	    end
197	  endgenerate*/
198	  
199	  stream_fifo_pipe_true #(.DATA_WIDTH(SOFT_THREAD*`XLEN+SOFT_THREAD+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP),
200	                          .FIFO_DEPTH(1)
201	    ) U_result(
202	              .clk        (clk             ),
203	              .rst_n      (rst_n           ),
204	              .w_valid_i  (result_in_valid ),
205	              .w_data_i   (result_data_in  ),
206	              .r_ready_i  (result_out_ready),
207	
208	              .w_ready_o  (result_in_ready ),
209	              .r_data_o   (result_data_out ),
210	              .r_valid_o  (result_out_valid)
211	            );
212	
213	  stream_fifo_pipe_true #(.DATA_WIDTH(`DEPTH_WARP+SOFT_THREAD),
214	                          .FIFO_DEPTH(1)
215	    ) U_result_simt(
216	              .clk        (clk                  ),
217	              .rst_n      (rst_n                ),
218	              .w_valid_i  (result_simt_in_valid ),
219	              .w_data_i   (result_simt_data_in  ),
220	              .r_ready_i  (result_simt_out_ready),
221	
222	              .w_ready_o  (result_simt_in_ready ),
223	              .r_data_o   (result_simt_data_out ),
224	              .r_valid_o  (result_simt_out_valid)
225	            );
226	  //result端口赋值
227	  assign  result_data_in   = {ctrl_wid_i,wb_wvd_rd_comb,ctrl_reg_idxw_i,ctrl_wvd_i,wvd_mask};
228	  assign  result_in_valid  = in_valid_i & ctrl_wvd_i & (!ctrl_simt_stack_i)                 ;
229	  //assign  result_in_valid  = in_valid_i & (ctrl_wvd_i || ctrl_alu_fn_i=='d8) & (!ctrl_simt_stack_i);
230	  assign  result_out_ready = out_ready_i                                                    ;
231	
232	  //result2simt端口赋值
233	  assign  result_simt_data_in   = {ctrl_wid_i,if_mask}          ;
234	  assign  result_simt_in_valid  = in_valid_i & ctrl_simt_stack_i;
235	  assign  result_simt_out_ready = out2simt_ready_i              ;
236	
237	  //result输出拆分
238	  assign  warp_id_o  = result_data_out[SOFT_THREAD*`XLEN+SOFT_THREAD+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-1-:`DEPTH_WARP];
239	  assign  wb_wvd_rd_o= result_data_out[SOFT_THREAD*`XLEN+SOFT_THREAD+`REGIDX_WIDTH+`REGEXT_WIDTH-:SOFT_THREAD*`XLEN]          ;
240	  assign  reg_idxw_o = result_data_out[SOFT_THREAD+`REGIDX_WIDTH+`REGEXT_WIDTH-:`REGIDX_WIDTH+`REGEXT_WIDTH]                  ;
241	  assign  wvd_o      = result_data_out[SOFT_THREAD]                                                                           ;
242	  assign  wvd_mask_o = result_data_out[SOFT_THREAD-1:0]                                                                       ;
243	  assign  out_valid_o= result_out_valid                                                                                       ;
244	  
245	  /*genvar k;
246	  generate 
247	    for(k=0;k<HARD_THREAD;k=k+1) begin
248	      wb_wvd_rd_o[k] = result_data_out[(k+1)*`XLEN+SOFT_THREAD+`REGIDX_WIDTH+`REGEXT_WIDTH:k*`XLEN+SOFT_THREAD+`REGIDX_WIDTH+`REGEXT_WIDTH+1];
249	    end
250	  endgenerate*/
251	
252	  //result_simt输出拆分
253	  assign  wid_o      = result_simt_data_out[`DEPTH_WARP+SOFT_THREAD-1:SOFT_THREAD];
254	  assign  if_mask_o  = result_simt_data_out[SOFT_THREAD-1:0]                      ;
255	  assign  out2simt_valid_o = result_simt_out_valid                                ;
256	
257	  assign  in_ready_o = ctrl_simt_stack_i ? result_simt_in_ready : result_in_ready ;
258	
259	endmodule
260	
261	
262

